/*! PHP-Bind-Dashboard app.min.js */
(function(){"use strict";function getPreferredTheme(){const stored=localStorage.getItem("pbd-theme");if(stored)return stored;return window.matchMedia("(prefers-color-scheme: dark)").matches?"dark":"light"}function setTheme(theme){if(theme==="auto"){document.documentElement.setAttribute("data-bs-theme",window.matchMedia("(prefers-color-scheme: dark)").matches?"dark":"light")}else{document.documentElement.setAttribute("data-bs-theme",theme)}localStorage.setItem("pbd-theme",theme);const icon=document.getElementById("themeIcon");if(icon){icon.className=theme==="dark"||(theme==="auto"&&window.matchMedia("(prefers-color-scheme: dark)").matches)?"fa-solid fa-sun":"fa-solid fa-moon"}}document.addEventListener("DOMContentLoaded",function(){setTheme(getPreferredTheme());const btn=document.getElementById("themeToggle");if(btn){btn.addEventListener("click",function(){const current=document.documentElement.getAttribute("data-bs-theme");const next=current==="dark"?"light":"dark";setTheme(next)})}})})();
